'use strict';
(function(){
 const B=JourneyBosses;
 for(const id of [...Object.keys(B.D).flatMap(id=>['boss_'+id,...(B.D[id].true?['boss_'+id+'_2']:[])]),'boss_seal']){const im=new Image();im.src=CA[id].sprite;for(const pose of ['idle','walk','attack'])IM[id+':'+pose]=im;IM[id]=im;}
 function names(){for(const [id,d]of Object.entries(B.D))for(const form of d.true?[1,2]:[1])G.BY['boss_'+id+(form===2?'_2':'')].name=L(d.en,d.pt)+(form===2?' II':'');G.BY.boss_seal.name=L('Crimson Seal','Selo carmesim');if(S?.bossEncounter){const e=S.bossEncounter,d=B.D[e.id];S.current.name=L(d.en,d.pt)+(e.form===2?' II':'');}}
 const baseRender=render;render=function(){names();return baseRender();};names();
 function rules(d){return d.true?L('Win two rounds to reveal Form II. Then defeat its persistent health bar before losing five rounds across both forms. Your team, energy and upgrades carry through the transformation.','Vença duas rodadas para revelar a Forma II. Depois esgote a vida persistente antes de perder cinco rodadas somando as duas formas. Sua equipe, energia e melhorias continuam na transformação.'):L('Win four rounds. The leader is present from round one and occupies a team slot. Defeat the entire enemy team to win a round.','Vença quatro rodadas. O líder está presente desde a primeira e ocupa uma vaga da equipe. Derrote todos os inimigos para vencer a rodada.');}
 function info(id,form=1,node=null){const d=B.D[id],t=G.BY['boss_'+id+(form===2?'_2':'')],p=form===2?1:JourneyActs.power(S);openModal('<div class="boss-modal-head"><div class="eyebrow">'+(d.true?'TRUE FINAL BOSS':'BOSS')+' · '+L('Form ','Forma ')+form+'</div><h2>'+esc(L(d.en,d.pt))+'</h2></div><div class="boss-modal-body"><img class="boss-art" src="'+CA[t.id].art+'" alt="'+esc(t.name)+'"><div class="boss-stats"><span>♥ '+Math.round(t.hp*p)+'</span><span>'+Icon('sword')+' '+Math.round(t.atk*p)+'</span><span>'+Icon('shield')+' '+t.defense+'</span><span>'+Icon('haste')+' '+d.aps+'/s</span></div><h3>'+L(d.skillEn,d.skillPt)+'</h3><p>'+L(d.descEn,d.descPt)+'</p><p>'+rules(d)+'</p>'+(d.true?'<p>'+L('Form II: ','Forma II: ')+d.hp2.toLocaleString()+' HP · '+d.atk2+' ATK · '+d.def2+' DEF</p>':'')+'</div><div class="boss-modal-footer">'+(node?metaButton('enter-node',L('Fight','Combater'),'data-id="'+node.id+'"','primary'):metaButton('close',L('Back','Voltar'),'','primary'))+'</div>');document.querySelector('#overlay>.modal').classList.add('boss-modal');}
 const guard=JourneyTraining.guard;JourneyTraining.guard=function(e){if(e.type==='click'){const el=e.target.closest?.('[data-act]');if(el?.dataset.act==='boss-info'){e.preventDefault();e.stopImmediatePropagation();if(S?.bossEncounter)info(S.bossEncounter.id,S.bossEncounter.form);return true;}if(el?.dataset.act==='node'&&S?.phase==='map'){const n=G.available(S).find(v=>v.id===el.dataset.id);if(n&&B.select(S,n)){e.preventDefault();e.stopImmediatePropagation();info(n.bossId,1,n);return true;}}}return guard(e);};
 const baseHud=raidHud;raidHud=function(){const html=baseHud();if(S?.bossEncounter?.id!=='primordial'||S.bossEncounter.form!==2)return html;const head=(S.round-1)%3;return html.replace('</b>',' · '+L(['Fire cone','Poison line','Close impact'][head],['Cone de fogo','Linha venenosa','Impacto próximo'][head])+'</b>');};
 const status=arenaStatus;arenaStatus=function(combat=false){let html=status(combat);if(!S?.bossEncounter)return html;const e=S.bossEncounter,d=B.D[e.id];let caption=(e.form===1?'I':'II')+' · '+L(d.en,d.pt);return html.replace(/<small>[^<]*<\/small>/,'<button type="button" class="boss-label" data-act="boss-info">'+esc(caption)+' ⓘ</button>');};
 const oldPrep=prep;prep=function(){names();oldPrep();if(!S?.bossEncounter||S.raid)return;const e=S.bossEncounter,type='boss_'+e.id;document.querySelector('.hidden-enemy')?.remove();const pos=GPosition(G.BY[type].range>100?12:2,1),a=CA[type],h=a.size[1]*a.scale*(88/112),w=h*a.size[0]/a.size[1],node=document.createElement('div');node.className='raid-preview';node.innerHTML='<img src="'+a.sprite+'" alt="'+esc(G.BY[type].name)+'" style="left:'+((pos.x-w/2)/430*100)+'%;top:'+((pos.y-h+8)/540*100)+'%;width:'+(w/430*100)+'%;height:'+(h/540*100)+'%">';document.querySelector('.arena-stage .field')?.append(node);};
 const result=resultView;resultView=function(){if(!S?.bossEncounter||!B.D[S.bossEncounter.id].true)return result();names();const e=S.bossEncounter,d=B.D[e.id],next=S.phase==='roundResult',transform=next&&e.transition,win=S.phase==='victory',type='boss_'+e.id+(transform||e.form===2?'_2':'');const title=transform?L('The true form awakens','A verdadeira forma desperta'):next?L('The battle continues','A batalha continua'):win?L('True Final Boss defeated!','True Final Boss derrotado!'):L('Journey ended','Fim da jornada');let mechanic=e.form===2&&e.id==='primordial'?L(['Next head: fire cone','Next head: poison line','Next head: close impact'][S.round%3],['Próxima cabeça: cone de fogo','Próxima cabeça: linha venenosa','Próxima cabeça: impacto próximo'][S.round%3]):'';show('<section class="training-result boss-result"><div class="eyebrow">TRUE FINAL BOSS · '+L('Form ','Forma ')+(transform?2:e.form)+'</div><h2>'+title+'</h2><img class="boss-result-art" src="'+CA[type].art+'" alt="'+esc(L(d.en,d.pt))+'"><div class="bigscore">'+S.score[0]+' : '+S.score[1]+'</div>'+(S.raid?raidHud():'')+(transform?'<p>'+L('Boss health persists between rounds. Five total round losses end the journey.','A vida do boss persiste entre rodadas. Cinco derrotas no total encerram a jornada.')+'</p><p>'+L(d.descEn.split('Form II: ')[1]||d.descEn,d.descPt.split('Forma II: ')[1]||d.descPt)+'</p>':'')+(mechanic?'<p>'+mechanic+'</p>':'')+damageReport()+(!next?metaResultPanel():'')+'<div class="training-sticky stack">'+(next?metaButton('next-round',transform?L('Face Form II','Enfrentar Forma II'):L('Prepare round ','Preparar rodada ')+(S.round+1),'','primary'):metaButton('home',L('Main menu','Menu principal'),'','primary')+metaButton('new',L('Choose another deck','Escolher outro baralho')))+'</div></section>');};
 const paint=paintCombat;paintCombat=function(now){paint(now);if(!battle?.boss)return;const q=battle.boss,u=B.leader(battle),c=$('combat').getContext('2d');if(!u)return;c.save();const warning=q.warning||q.windup;if(warning){c.strokeStyle='#f8c1ff';c.fillStyle='#b97bf238';c.setLineDash([5,4]);c.lineWidth=3;c.beginPath();if(q.windup){const a=Math.atan2(warning.dy,warning.dx);c.moveTo(u.x,u.y);c.arc(u.x,u.y,150,a-1.3,a+1.3);c.closePath();}else if(q.id==='darkelf'||q.id==='primordial'&&q.head===1){const a=warning.angle,dx=Math.cos(a),dy=Math.sin(a),w=q.id==='darkelf'?24:38;c.moveTo(u.x-dy*w,u.y+dx*w);c.lineTo(u.x+dx*600-dy*w,u.y+dy*600+dx*w);c.lineTo(u.x+dx*600+dy*w,u.y+dy*600-dx*w);c.lineTo(u.x+dy*w,u.y-dx*w);c.closePath();}else if(q.id==='primordial'&&q.head===0){c.moveTo(u.x,u.y);c.arc(u.x,u.y,600,warning.angle-.45,warning.angle+.45);c.closePath();}else if(q.id==='primordial')c.arc(u.x,u.y,165,0,Math.PI*2);else c.arc(warning.x,warning.y,q.id==='titan'?80:65,0,Math.PI*2);c.fill();c.stroke();c.setLineDash([]);}
 if(q.form===2&&q.id!=='fairy'){c.fillStyle='#101c30dd';c.fillRect(90,25,250,24);c.font='17px VT323';c.textAlign='center';c.fillStyle='#ffdf98';let label=q.id==='titan'?(battle.time<q.staggerUntil?L('EXPOSED · +40% damage','EXPOSTO · +40% dano'):L('Instability ','Instabilidade ')+q.instability+'/18'):q.id==='darkelf'?(battle.units.filter(v=>v.side&&v.hp>0&&!v.raidBoss).length?L('Break the three seals','Quebre os três selos'):L('EXPOSED · +25% damage','EXPOSTO · +25% dano')):q.id==='primordial'?L(['FIRE CONE','POISON LINE','CLOSE IMPACT'][q.head],['CONE DE FOGO','LINHA VENENOSA','IMPACTO PRÓXIMO'][q.head]):'';c.fillText(label,215,42);}c.restore();};
})();
